using System;using System.IO;using System.Linq;using System.Threading.Tasks;using System.Windows;using System.Windows.Controls;using System.Collections.Generic;using DualSteam.UI;
public partial class App {
 string selectedGame="",selectedSettings="";SettingsScan settingsScan;StackPanel scanResults;TextBlock scanSummary;TextBox destinationInput;
 string PickFolder(string title){using(var dialog=new System.Windows.Forms.FolderBrowserDialog{Description=title,ShowNewFolderButton=false})return dialog.ShowDialog()==System.Windows.Forms.DialogResult.OK?dialog.SelectedPath:null;}
 FrameworkElement Sharing(){
  var body=Stack();Heading("Sharing","Find and copy game settings from Main Steam to Second Steam.",body);
  var picker=Stack();picker.Children.Add(Text("GAME FOLDER",12,"text.muted",true));picker.Children.Add(Text(String.IsNullOrEmpty(selectedGame)?"Choose an installed game's folder to look for its settings.":selectedGame,13,"text.secondary"));
  var buttons=new WrapPanel();var choose=ActionButton("Choose game folder",()=>{string folder=PickFolder("Choose the game's installed folder");if(folder!=null){selectedGame=folder;selectedSettings="";settingsScan=null;ShowPage("Sharing");RunSettingsScan();}},true);choose.Margin=new Thickness(0,12,8,8);buttons.Children.Add(choose);
  var manual=ActionButton("Choose settings folder",()=>{if(String.IsNullOrEmpty(selectedGame)){toast.Show("Choose the installed game folder first.");return;}string folder=PickFolder("Choose the folder containing this game's settings");if(folder!=null){selectedSettings=folder;RunSettingsScan();}});manual.Margin=new Thickness(0,12,8,8);buttons.Children.Add(manual);var rescan=ActionButton("Scan again",RunSettingsScan);rescan.Margin=new Thickness(0,12,0,8);buttons.Children.Add(rescan);picker.Children.Add(buttons);body.Children.Add(Group(picker));
  body.Children.Add(new InfoBanner("Close the game in both clients first. Review each file: this copies complete text files, not individual options. A matching name does not guarantee that every setting is portable between accounts."));
  scanSummary=Text("Choose a game to begin. Nothing is copied automatically.",13,"text.secondary");scanSummary.Margin=new Thickness(0,20,0,12);body.Children.Add(scanSummary);
  scanResults=Stack();body.Children.Add(scanResults);
  var target=Stack();target.Children.Add(Text("DESTINATION",12,"text.muted",true));target.Children.Add(Text("Detected profile paths map to the same location in Second Steam's Windows profile. For a manually selected settings folder, you can enter a different relative folder below.",13,"text.secondary"));destinationInput=new TextBox{Text="",Margin=new Thickness(0,12,0,8),Padding=new Thickness(10),MinHeight=36};Theme.Bind(destinationInput,Control.BackgroundProperty,"bg.surfaceRaised");Theme.Bind(destinationInput,Control.ForegroundProperty,"text.primary");Ui.Name(destinationInput,"Custom destination relative to second Windows profile");target.Children.Add(destinationInput);target.Children.Add(Text(@"Optional example: Documents\My Game\Config. Leave blank to use each detected path. Shared game-install folders and Steam userdata are not automatic destinations.",12,"text.muted"));body.Children.Add(Group(target));
  var actions=new WrapPanel();var copy=ActionButton("Copy selected settings",CopySettings,true);copy.Margin=new Thickness(0,0,8,8);actions.Children.Add(copy);var restore=ActionButton("Restore last import",()=>Act(()=>{string result=SettingsScanner.Restore();Dispatcher.Invoke(()=>{if(sharingStatus!=null)sharingStatus.Text=result;});},"Previous settings restored."));restore.Margin=new Thickness(0,0,0,8);actions.Children.Add(restore);body.Children.Add(actions);
  sharingStatus=Text("No files copied in this session.",13,"text.secondary");body.Children.Add(Group(sharingStatus));body.Children.Add(Text("Backups are kept under the second profile's Evidence / Settings Imports folder. Restore stops if a destination has changed since import. Millennium imports remain in Settings → Compatibility.",12,"text.muted"));if(settingsScan!=null)ShowSettingsScan();return body;
 }
 async void RunSettingsScan(){if(busy)return;if(String.IsNullOrEmpty(selectedGame)){toast.Show("Choose an installed game folder first.");return;}busy=true;settingsScan=null;scanResults.Children.Clear();scanSummary.Text="Scanning settings folders…";try{string game=selectedGame,custom=selectedSettings;settingsScan=await Task.Run(()=>SettingsScanner.Scan(game,custom));if(page=="Sharing")ShowSettingsScan();}catch(Exception ex){Engine.Log(ex.ToString());if(page=="Sharing")scanSummary.Text=ex.Message;}finally{busy=false;}}
 void ShowSettingsScan(){if(scanResults==null||settingsScan==null)return;scanResults.Children.Clear();scanSummary.Text=settingsScan.Name+(String.IsNullOrEmpty(settingsScan.AppId)?"":" · Steam App "+settingsScan.AppId)+" · "+settingsScan.Files.Count+" settings candidates · "+settingsScan.Skipped+" files excluded";
  foreach(var file in settingsScan.Files){var item=file;var stack=Stack();var check=new CheckBox{Content=Path.GetFileName(file.Source)+" · "+Math.Max(1,file.Size/1024)+" KB",IsChecked=file.Selected,Margin=new Thickness(0,0,0,8)};Theme.Bind(check,Control.ForegroundProperty,"text.primary");check.Checked+=(s,e)=>item.Selected=true;check.Unchecked+=(s,e)=>item.Selected=false;stack.Children.Add(check);stack.Children.Add(Text("From: "+file.Source,12,"text.muted"));stack.Children.Add(Text("To: "+(String.IsNullOrEmpty(file.Relative)?"Enter a custom destination folder below before copying.":Path.Combine(Engine.ProfileRoot,file.Relative)),12,"text.secondary"));var inspect=ActionButton("Review file",()=>{try{System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo("notepad.exe",Engine.Quote(item.Source)){UseShellExecute=false});}catch(Exception ex){toast.Show(ex.Message);}});stack.Children.Add(inspect);scanResults.Children.Add(Group(stack));}
  foreach(string note in settingsScan.Notes){var text=Text(note,12,"text.muted");text.Margin=new Thickness(0,0,0,12);scanResults.Children.Add(text);}
 }
 void CopySettings(){if(settingsScan==null){toast.Show("Scan a game folder first.");return;}if(Engine.Current==null){toast.Show("Set up Second Steam first.");return;}var scan=settingsScan;var selected=scan.Files.Where(f=>f.Selected).ToArray();if(selected.Length==0){toast.Show("Select the files you want to copy.");return;}string custom=destinationInput.Text;
  string preview=String.Join("\n",selected.Take(8).Select(f=>Path.GetFileName(f.Source)+" → "+(String.IsNullOrWhiteSpace(custom)?f.Relative:custom)))+(selected.Length>8?"\n…":"");
  if(AppDialog.Show(window,"Copy "+selected.Length+" complete settings files into Second Steam's Windows profile? Existing files will be backed up.\n\n"+preview,"Review settings import",MessageBoxButton.YesNo,MessageBoxImage.Question)!=MessageBoxResult.Yes)return;
  Act(()=>{string result=SettingsScanner.Copy(scan,selected,custom);Dispatcher.Invoke(()=>{settingsScan=null;if(page=="Sharing"){scanResults.Children.Clear();scanSummary.Text="Import complete. Scan again before copying more files.";sharingStatus.Text=result;}});},"Selected settings copied.");
 }
}
